import{_ as t,o as s,c as r,ag as e}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"科学日报 · 2026-10-24（材料 / 增材制造单晶 / 可穿戴织物计算）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/materials/science-daily-2026-10-24-materials.md","filePath":"topics/materials/science-daily-2026-10-24-materials.md"}'),i={name:"topics/materials/science-daily-2026-10-24-materials.md"};function n(a,o,l,c,g,d){return s(),r("div",null,[...o[0]||(o[0]=[e('<h1 id="科学日报-·-2026-10-24-材料-增材制造单晶-可穿戴织物计算" tabindex="-1">科学日报 · 2026-10-24（材料 / 增材制造单晶 / 可穿戴织物计算） <a class="header-anchor" href="#科学日报-·-2026-10-24-材料-增材制造单晶-可穿戴织物计算" aria-label="Permalink to &quot;科学日报 · 2026-10-24（材料 / 增材制造单晶 / 可穿戴织物计算）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-24.md</code> — 第43期 ｜ 科学板块（2 篇） 落盘说明：文件名带 <code>-materials</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-24-金属-3d-打印也能长「米级单晶」——用交错-脉冲热输入一次性消掉晶界" tabindex="-1">科学日报 2026-10-24：金属 3D 打印也能长「米级单晶」——用交错/脉冲热输入一次性消掉晶界 <a class="header-anchor" href="#科学日报-2026-10-24-金属-3d-打印也能长「米级单晶」——用交错-脉冲热输入一次性消掉晶界" aria-label="Permalink to &quot;科学日报 2026-10-24：金属 3D 打印也能长「米级单晶」——用交错/脉冲热输入一次性消掉晶界&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-24.md</code> ｜ DOI: 10.1038/s41586-026-11185-0</p></blockquote><ul><li>矛盾的本质：单晶性能优异，但其制备依赖<strong>严格准稳态的热条件</strong>；而<strong>增材制造天然是剧烈循环热波动</strong>（熔池快速往复）。二者要求<strong>方向相反</strong> → 大型/带架构的三维打印单晶长期做不到。</li><li>解法：<strong>自由形貌增材制造 + 精密控制的「交替 + 脉冲」热输入</strong>来<strong>引导（而非只是维持）单晶生长</strong>。</li><li>成果： <ul><li><strong>米级高、厘米级直径的 Ti-6Al-4V 单晶</strong>；</li><li><strong>首个含复杂之字形（zigzag）连杆的单晶点阵结构</strong> —— 实质取消单晶构件的尺寸上限；</li><li><strong>抗蠕变比「晶粒尺寸标度」外推高约一个数量级</strong>，源于<strong>晶界被彻底消除</strong> + 增材诱导的<strong>层级 α/β 结构</strong>调控了<strong>位错密度、迁移率与孔洞演化</strong>；</li><li>普适性：<strong>W、Mo、Nb、MoNb 合金</strong>等难加工难熔金属单晶亦可打印。</li></ul></li><li>洞察（对本库 <code>materials</code>）：这是一条**「把约束的反面变成工具」<strong>的范例。以往把循环热波动视为「增材制造的缺陷来源」，本条把它当成</strong>驱动晶体取向选择的手段**（脉冲/交替 = 给晶粒生长施加可控的「方向性」）。对照本库既有主线——10-21「螺旋位错把旋性写进晶体」、10-22「酶热嵌进聚酯让降解可编程」、10-23「分子筛把分子摆对笼子决定产物」——<strong>同族动作都是『把几何/时序当作指令』</strong>：这里被编程的量是<strong>热历史（时间维度上的几何）</strong>。可迁移判据：<strong>当你无法消除一个干扰，先问这个干扰携带的信息能否被用来做选择。</strong></li></ul><hr><h2 id="科学日报-2026-10-24-把-gui-织进袖子——可数字寻址的「像素纤维」让织物自己变成计算机" tabindex="-1">科学日报 2026-10-24：把 GUI 织进袖子——可数字寻址的「像素纤维」让织物自己变成计算机 <a class="header-anchor" href="#科学日报-2026-10-24-把-gui-织进袖子——可数字寻址的「像素纤维」让织物自己变成计算机" aria-label="Permalink to &quot;科学日报 2026-10-24：把 GUI 织进袖子——可数字寻址的「像素纤维」让织物自己变成计算机&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-24.md</code> ｜ DOI: 10.1038/s41586-026-11128-9</p></blockquote><ul><li>维度错配：可穿戴计算前景巨大，但传统 GUI 依赖<strong>平面刚性显示屏</strong>，而纺织品的本质是<strong>一维纤维</strong> —— 二者维度不匹配，已有的柔性/纤维显示无法提供交互 GUI 所需的<strong>可数字寻址、高吞吐、信息丰富</strong>的界面。</li><li>器件：<strong>数字像素纤维</strong>，三件套集成在一根纤维里： <ul><li><strong>可寻址像素</strong>；</li><li>沿传播轴的<strong>公共互连</strong>（让纤维内电路可扩展）；</li><li><strong>同轴传感层</strong>（实现纤维级触摸定位）。</li></ul></li><li>架构：微电子元件 + <strong>触摸门控的电阻通路系统</strong>构成一条<strong>线性电路</strong>，同时充当<strong>交互显示主干</strong>与<strong>计算总线</strong>；外围多模态纤维传感器/致动器提供<strong>生理、惯性、光学、声学</strong>的输入输出。</li><li>演示：把纤维织进<strong>衣袖前臂部分</strong>，做出 <strong>96 × 54 像素、30 fps、8-bit 色深</strong>的 GUI，支持<strong>动态图形、音视频播放、无线数据交换与交互式计算</strong>，并保持日常纺织品的<strong>柔性、可水洗、透气与机械强度</strong>。</li><li>洞察（对本库 <code>materials</code> × <code>design</code>）：本条把「<strong>显示、传感、计算三合一塞进一根纤维</strong>」——单位元件的功能密度是关键，而非屏幕尺寸。这与其说是显示技术的进步，不如说是**「把总线做进结构里」<strong>：电路的互连与纤维的物理轴重合，于是</strong>可扩展性来自纺织工艺本身（织多少根就是多大算力/多少像素）**。与本库 10-09「晶圆级低对称石墨烯莫尔整流器」、10-21「织物用户界面」同族：<strong>结构与功能一体化（structural electronics）</strong>。迁移判据：<strong>当一个系统受限于「元件之间的连接」而非「元件本身」，就让连接成为元件的一部分。</strong></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/materials/index.md</code> ｜ 第43期 科学板块</p></blockquote><p>关键词：增材制造单晶、alternating and pulsed heat input、自由形貌、Ti-6Al-4V 米级单晶、之字形连杆单晶点阵、抗蠕变高一个数量级、消除晶界、层级 α/β 结构、位错密度与孔洞演化、W/Mo/Nb/MoNb 难熔金属、热历史即指令、缺陷当工具；数字像素纤维、digital pixel fibre、可寻址像素、同轴传感层、触摸门控电阻通路、计算总线、96x54 像素 30fps 8-bit、可水洗透气、结构电子学、连接成为元件一部分、可扩展性来自纺织工艺</p><p>关联：<code>topics/materials/science-daily-2026-10-23-materials.md</code>（分子筛限域 + 反铁磁 OTT）、<code>topics/materials/science-daily-2026-10-22-materials.md</code>（嵌酶聚酯 + 人工金属酶）、<code>topics/physics/science-daily-2026-10-24-physics.md</code>、<code>topics/materials/index.md</code></p>',14)])])}const u=t(i,[["render",n]]);export{m as __pageData,u as default};
